css_snippet:
:root {
  --base-font-size: 1rem;
  --base-line-height: 1.5;
  --vertical-rhythm-unit: calc(var(--base-font-size) * var(--base-line-height));
}

body {
  font-size: var(--base-font-size);
  line-height: var(--base-line-height);
}

h1 {
  font-size: 2.5rem;
  line-height: 1.2;
  margin-top: var(--vertical-rhythm-unit);
  margin-bottom: var(--vertical-rhythm-unit);
}

p {
  margin-bottom: var(--vertical-rhythm-unit);
}

.section-spacing {
  padding-top: calc(2 * var(--vertical-rhythm-unit));
  padding-bottom: calc(2 * var(--vertical-rhythm-unit));
}
